//! Collection tools shared by the main photo and editorial sequence controls.
use super::{ctx, update_field, Edit};
use crate::photography;
use leptos::prelude::*;

#[component]
pub(super) fn CollectionPicker(state: Edit) -> impl IntoView {
    let user=ctx().session.get_value().user.id;let stored=StoredValue::new(state);
    let category=RwSignal::new(String::new());let query=RwSignal::new(String::new());
    let filtered=move||photography::collection().iter().filter(|p|p.matches(&category.get(),&query.get())).cloned().collect::<Vec<_>>();
    view!{<details class="photo-library" open><summary>"Choose from the trail collection"<span>{format!("{} photographs",photography::collection().len())}</span></summary><p class="small-note">"Choosing a photograph adds its description, dated caption and credit. Historical material keeps its original context."</p><div class="collection-controls"><label class="field"><span>"Search photos"</span><input type="search" placeholder="Place, subject or photographer" prop:value=move||query.get() on:input=move|e|query.set(event_target_value(&e))/></label><label class="field"><span>"Photo subject"</span><select aria-label="Photo subject" prop:value=move||category.get() on:change=move|e|category.set(event_target_value(&e))><option value="">"All subjects"</option>{photography::CATEGORIES.iter().map(|c|view!{<option value=*c>{*c}</option>}).collect_view()}</select></label></div><p class="small-note" role="status">{move||format!("{} photographs shown",filtered().len())}</p><div class="curated-photos">{move||filtered().into_iter().map(|p|{let active=p.file.clone();view!{<button type="button" class="curated-photo" aria-label=format!("Choose {}",p.caption) aria-pressed=move||(stored.get_value().get().draft.field("image")==active).to_string() on:click=move|_|{for(key,value)in[("image",p.file.clone()),("image_alt",p.alt.clone()),("credit",p.credit.clone()),("photo_caption",p.caption.clone()),("image_x","50".into()),("image_y","50".into())]{update_field(&stored.get_value(),key,value,user);}}><img src=p.small_file.clone() alt="" loading="lazy"/><span>{p.caption.clone()}</span></button>}}).collect_view()}</div><Show when=move||filtered().is_empty()><p class="small-note">"No photographs match. Try a different subject or search."</p></Show>{move||photography::by_file(&stored.get_value().get().draft.field("image")).map(|p|view!{<div class="collection-source"><strong>{p.credit.clone()}</strong><span>{p.license.clone()}</span><a href=p.source.clone() target="_blank" rel="noopener noreferrer">"View original record"</a><a href=p.license_url.clone() target="_blank" rel="noopener noreferrer">"License details"</a></div>})}</details>}
}

#[component]
pub(super) fn EditorialPhotos(state: Edit) -> impl IntoView {
    let user=ctx().session.get_value().user.id;let stored=StoredValue::new(state);
    view!{<section class="editor-panel"><h2>"Photo sequence & map"</h2><p class="small-note">"Add a pair of photographs throughout the story. The collection supplies verified captions, dates and credits. Existing stories use their editorial selection until you choose another image."</p>{[("essay_photo_1","First supporting photograph"),("essay_photo_2","Second supporting photograph")].into_iter().map(|(key,label)|view!{<div class="field"><label for=key>{label}</label><select id=key prop:value=move||stored.get_value().get().draft.field(key) on:change=move|e|update_field(&stored.get_value(),key,event_target_value(&e),user)><option value="">"Use editorial selection"</option><option value="none">"No photograph in this position"</option>{photography::CATEGORIES.iter().map(|category|view!{<optgroup label=*category>{photography::collection().iter().filter(|p|p.category==*category).map(|p|view!{<option value=p.name.clone()>{p.caption.clone()}</option>}).collect_view()}</optgroup>}).collect_view()}</select>{move||photography::named(&stored.get_value().get().draft.field(key)).map(|p|view!{<div class="essay-photo-preview"><img src=p.small_file alt=p.alt loading="lazy"/><small>{p.caption}</small></div>})}</div>}).collect_view()}<div class="field"><label for="story-map">"Supporting map"</label><select id="story-map" prop:value=move||stored.get_value().get().draft.field("story_map") on:change=move|e|update_field(&stored.get_value(),"story_map",event_target_value(&e),user)><option value="">"Use editorial map"</option><option value="none">"No map"</option><option value="whole-trail">"Whole historic trail"</option>{crate::explorer::STOPS.iter().map(|(id,name)|view!{<option value=*id>{*name}</option>}).collect_view()}</select><small>"Orientation only. Verified coordinates stay fixed."</small></div></section>}
}
